int EditScreen (int current)
{
	int i,x,y;
	char ch;
	clrscr();
	puts (banner);

	gotoxy (3,3);
	cprintf ("   editing character %d.%s\n\n", current, character_names[current]);
	gotoxy (3,4);
	cprintf ("  enter the number of an option");
	gotoxy (3,5);
	cprintf ("          to change it.\n");

	x = 3; y = 8;
	for (i = 0; i < 3; ++i)
	{
		gotoxy (x, y++);
		cprintf ("%d.%s",i+1,basic_vars[i].longname);
	}

	x = 17; y = 8;
	for (i = 3; i < 8; ++i)
	{
		gotoxy (x, y++);
		cprintf ("%d.%s",i+1,basic_vars[i].longname);
	}

	gotoxy (3, 14);
	cprintf ("0.go back");
	gotoxy (17, 14);
	cprintf ("9.save changes");

	PrintValues();

	for (;;)
	{
		ch = cgetc();
		i = ch - '0';
		if (i == 0)
		{
			return -1;
		}
		else if (i == 9)
		{
			SaveChanges(current);
		}
		else if (i >= 1 && i < 9)
		{
			EditValue (i-1);
			PrintValues();
		}
	}

	return -1;
}



