				break;
			case 1:
				result = CharacterSelectScreen();
				if (result == -1)
					state = 0;
				else
				{
					current_char = result;
					state = 2;
				}
				break;
			case 2:
				result = LoadSaveFiles (current_char);
				if (result == -1)
					state = 1;
				else
					state = 3;
				break;
			case 3:
				result = EditScreen (current_char);
				if (result == -1)
					state = 1;
				break;
		}
	}

	return 0;
}

