   ch_level/=ch_summ;
   volume=ch_level;
  }
  level+=volume;
  if (volume>max) max=volume;
  if (volume<min) min=volume;
 }
 if (n!=0) level/=n;
 int center=(max+min)/2;
 level=(level+center)/2;
 return((unsigned char)level);
}

