  Core::conf = conf;
  audio_handler = NULL;
  status = s_noise;
  sample_index = 0;

  // band pass order 8 Butterworth IIR filter [ 500, 11025 ] MHz.
  /*  FLT filter_a[] = {  1.0, -5.970353296423300, 15.684630463761362,
		      -23.789823575255049,     22.870304869869656,
