#!/usr/bin/perl
################################################################################
##
## (c) Copyright 2023 ZXjogv <zx@jogv.es>
## 
## This code is published under a GNU GPL license version 3 or later.  See
## LICENSE file in the distribution for details.
## 
################################################################################
##
## snapcheck.pl: given a snapshot of a given ZX Spectrum program or game,
## ensures that a set of constraints and conditions are met by the
## snapshotted program: values in given memory positions, register ranges,
## etc.
##
## Use case: when there is a bug in a RAGE1 program, there are some things
## that always need to be right: the screen number, number of sprites,
## animation sequences, stack pointer value in range, etc.
##
## Snapshot file must be in SZX (zx-state) format.
##

use strict;
use warnings;
use utf8;
use v5.20;

use FindBin;
use lib "$FindBin::Bin/../lib";
use Data::Dumper;
use Getopt::Std;

use Snapcheck::SZX;
use Snapcheck::MapFile;
use Snapcheck::Rules;

our ( $opt_f, $opt_c, $opt_d, $opt_m );
getopts( 'f:c:dm:' );

# read snapshot data from file
my $snap_file = $opt_f;
if ( not defined( $snap_file ) ) {
    die "usage: $0 -f <snapshot_file.szx> [-d] [-c <check_rules.cfg>] [-m <mapfile>]\n";
}
my $snapshot = szx_read_file( $snap_file );

# get debug flag
my $debug = defined( $opt_d );

# if debug, report on the file
if ( $debug ) {
    print "\nSnapshot File Structure:\n";
    foreach my $block ( @{ $snapshot->{'blocks'} } ){
        printf "  [%-4s] %d bytes", $block->{'id'}, $block->{'size'};

        if ( $block->{'id'} eq 'RAMP' ) {
            printf " - Page: %d", $block->{'data'}{'page_no'};
            printf " - Size: %d bytes", $block->{'data'}{'size'};
            if ( $block->{'data'}{'is_compressed'} ) {
                printf " - Compressed size: %d bytes", $block->{'data'}{'compressed_size'};
            }
        }

        if ( $block->{'id'} eq 'SPCR' ) {
            printf " - Border: %d - Port_7ffd: 0x%02X - Port_1ffd: 0x%02X - Port_fe: 0x%02X",
                map { $block->{'data'}{ $_ } } qw( border port_7ffd port_1ffd port_fe );
        }

        if ( $block->{'id'} eq 'Z80R' ) {
            printf " - AF=0x%04X, BC=0x%04X, DE=0x%04X, HL=0x%04X, PC=0x%04X, SP=0x%04X [...]",
                map { $block->{'data'}{ $_ } } qw( af bc de hl pc sp );
        }

        print "\n";
    }
}

# if debug, dump the 48K RAM in hexdump format
if ( $debug ) {
    print "\nRAM Dump:\n";
    my @bytes = unpack( 'C*', $snapshot->{'data'}{'ram'} );
    my $address = 0x4000;
    while ( @bytes ) {
        my @line_bytes = splice( @bytes, 0, 16 );
        printf "  %04X  %s  %s\n",
            $address,
            join( ' ', map { sprintf( '%02X', $_ ) } @line_bytes ),
            join( '', map { ( ( $_ >= 32 ) and ( $_ < 127 ) ) ? chr($_) : '.' } @line_bytes );
        $address += 16;
    }
}

# if -m file was provided, load symbols from map file
my $symbols;
if ( defined( $opt_m ) ) {
    $symbols = mapfile_load_address_symbols( $opt_m );
    if ( $debug ) {
        print "\nLoaded Address Symbols:\n";
        print join( "\n", map { sprintf( '  %-30s = 0x%04X', $_, $symbols->{ $_ } ) } sort keys %$symbols ), "\n";
    }
}

# if -c file was provided, check rules in the file
my $rules_file = $opt_c;

dima-umkk-tapplayer-src-main-java-ru-dmi.text:
package ru.dmitry.anokhin.zx.tapplayer;

import javax.sound.sampled.*;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class Application {

    public static void main(String[] args) throws Exception {
        // Param for playback (input) device.
        Line.Info playbackLine = new Line.Info(SourceDataLine.class);
        // Param for capture (output) device.
        Line.Info captureLine = new Line.Info(TargetDataLine.class);

        List<Mixer.Info> playbackDevices = filterDevices(playbackLine);
        List<Mixer.Info> captureDevices = filterDevices(captureLine);

        System.out.println("\nPlayback devices:");
        printInfo(playbackDevices);
//        System.out.println("\nCapture devices:");
//        printInfo(captureDevices);

        if(args.length != 3) {
            System.out.println("\nUsage: java -jar tapplayer.jar <output device number> <volume(0..10)> <input file>");
            System.exit(1);
        }

        new Application().start(args[2], playbackDevices.get(Integer.parseInt(args[0])-1), Integer.parseInt(args[1]));
    }

    float volume = 0.1f;

    private void start(String tapfile, Mixer.Info info, int vol) throws LineUnavailableException, IOException, InterruptedException {
        volume = vol / 10f;
        TapFile tap = new TapFile(tapfile);
        AudioFormat af = new AudioFormat(44100, 8, 1, true, false);
        SourceDataLine sdl = AudioSystem.getSourceDataLine(af, info);
        sdl.open(af);
        sdl.start();

        for(TapBlock block: tap.getBlocks()) {
            //pilot pulse
            for(int p=0; p<3000; p++) {
                pilotPulse(sdl);
            }
            syncPulse(sdl); //sync pulse
            //data pulses
            for(int i=0; i<block.getData().length; i++) {
                for(int bits=7; bits>=0; bits--) {
                    if((block.getData()[i] & (1 << bits)) != 0) {
                        onePulse(sdl);
                    } else {
                        zeroPulse(sdl);
                    }
                }
            }

            Thread.sleep(2000);
        }

        sdl.drain();
        sdl.close();
    }

    //zero = (0.25-0.5 ms)
    //one = (0.5-1 ms)
    //pilot = (1-2 ms)


    private void pilotPulse(SourceDataLine sdl) {
        int len = 55;
        byte[] buff = new byte[len];
        for(int i=0; i<len/2; i++) {
            buff[i] = (byte)(120*volume);
        }
        for(int i=len/2; i<len; i++) {
            buff[i] = (byte)(-120*volume);
        }
        sdl.write(buff,0,len);
    }

    private void onePulse(SourceDataLine sdl) {
        byte[] buff = new byte[43];
        for(int i=0; i<21; i++) {
            buff[i] = (byte)(120*volume);
        }
        for(int i=21; i<43; i++) {
            buff[i] = (byte)(-120*volume);
        }
        sdl.write(buff,0,43);
    }

    private void zeroPulse(SourceDataLine sdl) {
        byte[] buff = new byte[22];
        for(int i=0; i<11; i++) {
            buff[i] = (byte)(120*volume);
        }
        for(int i=11; i<22; i++) {
            buff[i] = (byte)(-120*volume);
        }
        sdl.write(buff,0,22);
    }

    private void syncPulse(SourceDataLine sdl) {
        byte[] buff = new byte[17];
        for(int i=0; i<8; i++) {
            buff[i] = (byte)(120*volume);
        }
        for(int i=8; i<17; i++) {
            buff[i] = (byte)(-120*volume);
        }
        sdl.write(buff,0,17);
    }


    private static void printInfo(List<Mixer.Info> devices) {
        int i=1;
        for (Mixer.Info info : devices) {
            System.out.printf("%d) Name [%s] Description [%s] ", i++, info.getName(), info.getDescription());
            System.out.println(info.getDescription());
        }
    }


    private static List<Mixer.Info> filterDevices(final Line.Info supportedLine) {
        List<Mixer.Info> result = new ArrayList<>();

        for (Mixer.Info info : AudioSystem.getMixerInfo()) {
            Mixer mixer = AudioSystem.getMixer(info);
            if (mixer.isLineSupported(supportedLine)) {
                result.add(info);
            }
        }
        return result;
    }

}

konamiman-msx-gradius-disassembly-makefi.text:
# Nemesis / Gradius (Konami, RC-742, 1986, MSX1) - desensamblado
#
# El orden de las cosas: trazar el flujo -> generar el listado -> comprobar que
# vuelve a dar la ROM byte a byte -> las comprobaciones que el reensamblado NO
# cubre.
#
# LO QUE CAMBIA RESPECTO A UN CARTUCHO DE 16 KB: esto es un MegaROM de 128 KB
# con el mapper Konami SIN SCC (Konami4), 16 bancos de 8 KB. Cada banco es un
# modulo (p00..p15) con su propio org -el sitio donde el mapper lo pone para
# ejecutarlo, ver tools/paginas.py-, su trazado, sus notas y su listado.
# `make verify` reensambla los 16 y los concatena: tiene que salir la ROM
# entera, byte a byte.
#
# Y una pieza que los cartuchos de 16 KB no necesitan: tools/bancos.py, que
# traza el CARTUCHO ENTERO llevando la cuenta de que banco hay en cada ranura.
# De ahi salen los src/pNN.entries -las llamadas que cruzan el mapper- y los
# src/pNN.nocode -las tablas del despachador-. `make semillas` los regenera.
#
# La ROM no se distribuye. Hace falta en la raiz como nemesis.rom, y
# `make comprueba` verifica el sha256.

ROM      = nemesis.rom
SHA      = 3210f8a0f2309dd4b9a89fc2b24d0f178ce4393a0a1f2854fbce545c361261bc
SRC      = src
WORK     = work
TITULO   = NEMESIS / GRADIUS - Konami (1986) - MSX1 - MegaROM RC-742 de 128 KB (Konami4)

PAGINAS  = 00 01 02 03 04 05 06 07 08 09 10 11 12 13 14 15

# Donde se ejecuta cada banco. Es la misma tabla que `python3 tools/paginas.py
# lista` (un test lo comprueba); esta copiada aqui para no lanzar python 32
# veces por cada make.
ORG_00 = 0x4000
ORG_01 = 0x6000
ORG_02 = 0x8000
ORG_03 = 0xa000
ORG_04 = 0x6000
ORG_05 = 0x8000
ORG_06 = 0xa000
ORG_07 = 0x8000
ORG_08 = 0xa000
ORG_09 = 0x8000
ORG_10 = 0xa000
ORG_11 = 0x8000
ORG_12 = 0xa000
ORG_13 = 0x8000
ORG_14 = 0x8000
ORG_15 = 0x8000
ORG    = $(ORG_$(1))

all: listado verify sanity test

$(ROM):
	@echo "=================================================================="
	@echo " Falta $(ROM), y este repositorio NO lo distribuye."
	@echo ""
	@echo " Es Nemesis / Gradius (Konami, RC-742, 1986) para MSX,"
	@echo " 131072 bytes exactos. Ponlo aqui con ese nombre."
	@echo " Para comprobar que es el mismo:"
	@echo "     shasum -a 256 $(ROM)"
	@echo "     $(SHA)"
	@echo ""
	@echo " Sin el se puede leer el listado ya generado en $(SRC)/, y los"
	@echo " tests que no dependen del binario siguen pasando."
	@echo "=================================================================="
	@false

comprueba: $(ROM)
	@echo "$(SHA)  $(ROM)" | shasum -a 256 -c -

# Reconocimiento: cabecera, escrituras al mapper, y la comprobacion de que la
# regla banco -> org la cumplen todas las escrituras. Es la base sobre la que
# se apoya todo lo demas.
reconoce: $(ROM)
	@python3 tools/reconocimiento.py $(ROM)

# La marca que Konami escondio al final del banco 3. El hallazgo es de
# Manuel Pazos (@ManuelPazosMSX), no nuestro.
marca: $(ROM)
	@python3 tools/marca_konami.py $(ROM)

# Los 16 bancos cortados de la ROM, uno por fichero.
$(WORK)/p00.bin: $(ROM) tools/paginas.py
	@mkdir -p $(WORK)
	python3 tools/paginas.py corta $(ROM) $(WORK)

paginas: $(WORK)/p00.bin

# Las semillas: el trazado de cartucho entero, que es el unico que sabe que
# banco hay en cada ranura. Reescribe los .entries y los .nocode.
semillas: $(ROM)
	python3 tools/bancos.py $(ROM) escribe $(SRC)

# El trazado sigue el flujo desde los puntos de entrada DE CADA BANCO.
define REGLA_TRAZA
$(WORK)/p$(1).trace.json: $(WORK)/p00.bin $(SRC)/p$(1).entries $(SRC)/p$(1).nocode tools/z80trace.py
	python3 tools/z80trace.py $(WORK)/p$(1).bin $(call ORG,$(1)) $(SRC)/p$(1).entries \
	        $(WORK)/p$(1) $(SRC)/p$(1).nocode
endef
$(foreach p,$(PAGINAS),$(eval $(call REGLA_TRAZA,$(p))))

trace: $(foreach p,$(PAGINAS),$(WORK)/p$(p).trace.json)

# Un listado por banco: src/nemesis_pNN.asm, con el org de ese banco.
define REGLA_LISTADO
$(SRC)/nemesis_p$(1).asm: $(WORK)/p$(1).trace.json $(SRC)/p$(1).notes tools/mkasm.py
	python3 tools/mkasm.py $(WORK)/p$(1).bin $(call ORG,$(1)) $(WORK)/p$(1).trace.json \
	        $(SRC)/p$(1).notes $(WORK)/msx.sym $(SRC)/nemesis_p$(1).asm \
	        "$(TITULO) - banco $(1) (se ejecuta en $(call ORG,$(1)))"
endef
$(foreach p,$(PAGINAS),$(eval $(call REGLA_LISTADO,$(p))))

listado: $(foreach p,$(PAGINAS),$(SRC)/nemesis_p$(p).asm)

# La prueba que decide si el desensamblado es fiable: cada banco reensambla a
# sus 8192 bytes, y los 16 concatenados dan la ROM entera.
verify: $(WORK)/p00.bin
	@for p in $(PAGINAS); do \
	  sh tools/verify_build.sh $(SRC)/nemesis_p$$p.asm $(WORK)/p$$p.bin \
	     `python3 tools/paginas.py org $$p` $(WORK)/p$$p.out.bin || exit 1; \
	done
	@sh tools/verify_rom.sh $(WORK) $(ROM) $(SHA)

# Lo que el reensamblado NO puede cazar: que unos datos se esten leyendo como
# codigo. El binario sale identico igual, porque los bytes no cambian; lo unico
# que cambia es lo que decimos de ellos.
sanity: trace
	@echo "=================================================================="
	@echo " la regla banco -> org la cumplen todas las escrituras al mapper"
	@echo "=================================================================="
	@python3 tools/reconocimiento.py $(ROM) | tail -1
	@echo "=================================================================="
	@echo " ningun byte declarado como datos puede salir como codigo"
	@echo "=================================================================="
	@for p in $(PAGINAS); do \
	  python3 tools/check_trace.py $(WORK)/p$$p.trace.json $(SRC)/p$$p.nocode | tail -1 || exit 1; \
	done
	@python3 tools/check_datos_como_codigo.py $(WORK) $(SRC)
	@echo "=================================================================="
	@echo " el trazado por bancos y el de cartucho entero dicen lo mismo"
	@echo "=================================================================="
	@python3 tools/check_bancos.py $(ROM) $(WORK) $(SRC)
	@echo "=================================================================="
	@echo " ningun punto de entrada puede caer dentro de una zona de datos"
	@echo "=================================================================="
	@for p in $(PAGINAS); do \
	  python3 tools/check_entradas.py $(SRC)/p$$p.entries $(SRC)/p$$p.notes \
	          $(SRC)/p$$p.nocode | tail -1 || exit 1; \
	done
	@echo "=================================================================="
	@echo " ni un byte del cartucho sin asignar (los 16 bancos)"
	@echo "=================================================================="
	@python3 tools/presupuesto.py $(WORK) $(SRC)

# Pone en los dos README las cifras que de verdad hay en el arbol. Los tests
# comparan las dos, asi que esto se corre despues de cada tanda de comentarios.
cifras:
	@python3 tools/cifras.py

densidad:
	@for p in $(PAGINAS); do \
	  echo "-- p$$p"; python3 tools/densidad.py $(SRC)/nemesis_p$$p.asm | tail -2; \
	done

test:
	@echo "=================================================================="
	@echo " Tests"
	@echo "=================================================================="
	@python3 -m unittest discover -s tests -v

# Las imagenes de la web NO son capturas: tools/graficos.py ejecuta en Python el
# descompresor de 0x49B9, el cargador de caracteres de 0x42FC y el montador de
# columnas de 0x46AE, y dibuja las pantallas y los doce mapas desde la ROM.
imagenes: $(ROM)
	@python3 tools/graficos.py

web: imagenes
	@python3 tools/md2html.py docs en
	@python3 tools/md2html.py docs/es es
	@python3 tools/make_web.py docs/imagenes docs/index.html en
	@python3 tools/make_web.py docs/imagenes docs/es/index.html es
	@python3 tools/check_enlaces.py docs

clean:
	rm -f $(WORK)/p*.trace.json $(WORK)/p*.blocks $(WORK)/p*.out.bin \
	      $(WORK)/nemesis_reensamblada.rom $(WORK)/pasmo.err

.PHONY: all comprueba reconoce marca paginas semillas trace listado verify \
        sanity cifras densidad test imagenes web clean
